package com.aoo.bcg.common.concurrency;import org.junit.jupiter.api.Test;import java.util.concurrent.*;import static org.junit.jupiter.api.Assertions.*;
class FutureBlockingGuardTest{@Test void boundedWorkerCannotWaitOnItsOwnQueuedFuture()throws Exception{try(var pool=Executors.newFixedThreadPool(1)){var result=new CompletableFuture<Throwable>();pool.execute(FutureBlockingGuard.worker("room",()->{var queued=pool.submit(()->1);try{FutureBlockingGuard.await(queued,1,TimeUnit.SECONDS);}catch(Throwable failure){result.complete(failure);}}));assertInstanceOf(IllegalStateException.class,result.get(200,TimeUnit.MILLISECONDS));}}}
